from dataclasses import dataclass
from typing import Set

from .cache import PlanCache


@dataclass
class Resolved:
    value: str
    lineage: Set[str]


class PlanResolver:
    def __init__(self, graph, cache: PlanCache):
        self.graph = graph
        self.cache = cache

    def resolve(self, name: str) -> Resolved:
        value, lineage = self._resolve(name, set())
        return Resolved(value, lineage)

    def _resolve(self, name: str, active: Set[str]):
        if name in active:
            raise ValueError("cyclic definition: " + name)
        cached = self.cache.get(name)
        if cached is not None:
            return cached, self.cache.lineage(name) or {name}
        dependencies, template = self.graph.lookup(name)
        active = set(active)
        active.add(name)
        values = {}
        lineage = {name}
        for dependency in dependencies:
            child_value, child_lineage = self._resolve(dependency, active)
            values[dependency] = child_value
            lineage.update(child_lineage)
        value = template.format(**values)
        self.cache.put(name, value, lineage)
        return value, lineage
